previewCss:
.darma-loader-darma-b9-traffic-light { width: calc(var(--loader-size, 96px) * .4); height: var(--loader-size, 96px); border-radius: calc(var(--loader-size, 96px) * .12); background: #1f2937; display: flex; flex-direction: column; align-items: center; justify-content: space-around; padding: calc(var(--loader-size, 96px) * .06) 0; box-sizing: border-box; }
.darma-loader-darma-b9-traffic-light span { width: 62%; aspect-ratio: 1; border-radius: 50%; }
.darma-loader-darma-b9-traffic-light span:nth-child(1) { background: #ef4444; animation: darma-loader-darma-b9-traffic-light-tl-a calc(var(--loader-speed, 1s) * 3) infinite; }
.darma-loader-darma-b9-traffic-light span:nth-child(2) { background: #f59e0b; animation: darma-loader-darma-b9-traffic-light-tl-b calc(var(--loader-speed, 1s) * 3) infinite; }
.darma-loader-darma-b9-traffic-light span:nth-child(3) { background: #22c55e; animation: darma-loader-darma-b9-traffic-light-tl-c calc(var(--loader-speed, 1s) * 3) infinite; }
@keyframes darma-loader-darma-b9-traffic-light-tl-a { 0%, 30% { opacity: 1; box-shadow: 0 0 calc(var(--loader-size, 96px) * .1) #ef4444; } 31%, 100% { opacity: .18; box-shadow: none; } }
@keyframes darma-loader-darma-b9-traffic-light-tl-b { 0%, 30% { opacity: .18; } 31%, 63% { opacity: 1; box-shadow: 0 0 calc(var(--loader-size, 96px) * .1) #f59e0b; } 64%, 100% { opacity: .18; } }
@keyframes darma-loader-darma-b9-traffic-light-tl-c { 0%, 63% { opacity: .18; } 64%, 100% { opacity: 1; box-shadow: 0 0 calc(var(--loader-size, 96px) * .1) #22c55e; } }

